import { Component, inject, input, signal } from '@angular/core';

@Component({
  selector: 'app-product-details',
  template: `<h2>{{ product()?.name }}</h2>`,
})
export class ProductDetails {
  private readonly api = inject(ProductApi); // fine: DI is ready
  readonly productId = input.required<string>();
  readonly product = signal<Product | undefined>(undefined);

  constructor() {
    // NG0950: the parent hasn't bound productId yet
    this.api.get(this.productId()).then((p) => this.product.set(p));
  }
}

import { Component, OnInit, inject, input, signal } from '@angular/core';

@Component({
  selector: 'app-product-details',
  template: `<h2>{{ product()?.name }}</h2>`,
})
export class ProductDetails implements OnInit {
  private readonly api = inject(ProductApi);
  readonly productId = input.required<string>();
  readonly product = signal<Product | undefined>(undefined);

  ngOnInit(): void {
    // Inputs hold the parent's first values here
    this.api.get(this.productId()).then((p) => this.product.set(p));
  }
}

